module tb;
    reg clk;
    reg load;
    reg [9:0] data;
    wire tc;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .load(load),
        .data(data),
        .tc(tc)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    initial begin
        // Initialize signals
        clk = 0;
        load = 0;
        data = 10'd0;

        @(posedge clk);
        #1;

        // Test 1: Reset / Initial state - load 0
        load = 1;
        data = 10'd0;
        @(posedge clk);
        #1;
        // With load=1 and data=0, count immediately goes to 0, tc should be 1
        if (tc !== 1'b1) begin
            errors = errors + 1;
            $display("Error: load=1 with data=0 did not assert tc (got %b)", tc);
        end

        // Test 2: Load a small count (e.g., 3 cycles)
        load = 1;
        data = 10'd3;
        @(posedge clk);
        #1;
        // On this rising edge, it loads 3. Synchronously or asynchronously depending on implementation,
        // let's check tc. At load=1, count=3, tc should be 0.
        if (tc !== 1'b0) begin
            errors = errors + 1;
            $display("Error: load=1 with data=3 should clear tc (got %b)", tc);
        end

        // Now deassert load and let it count down: 3 -> 2 -> 1 -> 0
        load = 0;

        // Cycle 1 (decrement to 2)
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin
            errors = errors + 1;
            $display("Error: tc asserted prematurely at cycle 1 (got %b)", tc);
        end

        // Cycle 2 (decrement to 1)
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin
            errors = errors + 1;
            $display("Error: tc asserted prematurely at cycle 2 (got %b)", tc);
        end

        // Cycle 3 (decrement to 0, tc should assert)
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin
            errors = errors + 1;
            $display("Error: tc not asserted when count reached 0 (got %b)", tc);
        end

        // Cycle 4 (should stay at 0 and tc should remain 1)
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin
            errors = errors + 1;
            $display("Error: tc did not stay asserted at 0 (got %b)", tc);
        end

        // Test 3: Reload while counting (interrupt countdown)
        // Load count of 5
        load = 1;
        data = 10'd5;
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin
            errors = errors + 1;
            $display("Error: Reloading 5 failed to clear tc (got %b)", tc);
        end

        // Count down 2 cycles (5 -> 4 -> 3)
        load = 0;
        @(posedge clk); // count becomes 4
        #1;
        @(posedge clk); // count becomes 3
        #1;

        // Now reload with 1 while it's in the middle of counting
        load = 1;
        data = 10'd1;
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin
            errors = errors + 1;
            $display("Error: Mid-count reload failed to clear tc (got %b)", tc);
        end

        // Next cycle should reach 0 (since loaded with 1)
        load = 0;
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin
            errors = errors + 1;
            $display("Error: Mid-count reload timer did not finish correctly (got %b)", tc);
        end

        // Final Result Evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
